def solve(w):
    n=len(w)
    if n<2: return 0
    dp=[[float("inf")]*n for _ in range(1<<n)]
    dp[1][0]=0
    for mask in range(1,1<<n):
        for u in range(n):
            for v in range(1,n):
                if not mask&(1<<v): dp[mask|(1<<v)][v]=min(dp[mask|(1<<v)][v],dp[mask][u]+w[u][v])
    return min(dp[-1][u]+w[u][0] for u in range(n))
